121	func TestNormalizeIPEquivalence(t *testing.T) {
122		pairs := [][]string{
123			{"127.0.0.1", "127.0.0.1"},
124			{"0:0:0:0:0:0:0:1", "::1"},
125			{"2001:DB8:0:0:0:0:0:1", "2001:db8::1"},
126			{"::ffff:192.0.2.1", "192.0.2.1"},
127			{"::", "::"},
128		}
129		for _, pair := range pairs {
130			for _, raw := range pair {
131				input := `{"timestamp":"2026-01-02T00:00:00Z","src_ip":"` + raw + `","action":"a"}`
132				results := runNormalize(t, input)
133				if results[0]["ok"] != true {
134					t.Fatalf("ip %q failed: %#v", raw, results[0])
135				}
136				got := eventOf(t, results[0])["source_ip"]
137				if got != pair[1] {
138					t.Fatalf("ip %q normalized to %v, want %q", raw, got, pair[1])
139				}
140			}
141		}
142	}
