166	func TestNormalizeTimestampFormats(t *testing.T) {
167		ok := map[string]string{
168			"2026-01-02T15:04:05Z":           "2026-01-02T15:04:05Z",
169			"2026-01-02T23:04:05+08:00":      "2026-01-02T15:04:05Z",
170			"2026-01-02T10:04:05-05:00":      "2026-01-02T15:04:05Z",
171			"2026-01-02T15:04:05.1Z":         "2026-01-02T15:04:05.1Z",
172			"2026-01-02T15:04:05.123456789Z": "2026-01-02T15:04:05.123456789Z",
173			"2026-01-02T15:04:05.100000000Z": "2026-01-02T15:04:05.1Z",
174			"2026-01-02T15:04:05.000000000Z": "2026-01-02T15:04:05Z",
175			"2026-01-02T15:04:05+00:00":      "2026-01-02T15:04:05Z",
176		}
177		for in, want := range ok {
178			results := runNormalize(t, `{"time":"`+in+`","action":"a"}`)
179			if results[0]["ok"] != true {
180				t.Fatalf("timestamp %q should parse, got %#v", in, results[0])
181			}
182			if got := eventOf(t, results[0])["timestamp"]; got != want {
183				t.Fatalf("timestamp %q -> %v, want %q", in, got, want)
184			}
185		}
186		bad := []string{
187			"2026-01-02T15:04:05",             // no timezone
188			"2026-01-02t15:04:05z",            // lowercase t/z
189			"2026-01-02T15:04:05.1234567890Z", // 10 fractional digits
190			"2026-01-02T15:04:05.123456789012Z",
191			"2026-01-02T15:04:05.Z",    // dot without digits
192			"2026-01-02T15:04:05+0800", // non-RFC3339 offset
193			"2026-13-02T15:04:05Z",     // month out of range
194			"not-a-time",
195		}
196		for _, in := range bad {
197			results := runNormalize(t, `{"time":"`+in+`","action":"a"}`)
198			if results[0]["ok"] != false {
199				t.Fatalf("timestamp %q should fail", in)
200			}
201			msg, _ := results[0]["error"].(string)
202			if !strings.Contains(msg, FieldTimestamp) {
203				t.Fatalf("error for timestamp %q must name field %q, got %q", in, FieldTimestamp, msg)
204			}
205		}
206	}
