1	// Log field normalization so detection rules can read logs from different
2	// sources through one canonical event shape.
3	package relayproof
4	
5	import (
6		"bufio"
7		"bytes"
8		"encoding/json"
9		"errors"
10		"fmt"
11		"io"
12		"net"
13		"sort"
14		"strings"
15		"time"
16	)
17	
18	// Canonical event field names.
19	const (
20		FieldTimestamp = "timestamp"
21		FieldSourceIP  = "source_ip"
22		FieldAction    = "action"
23	)
24	
25	// fieldAliases maps accepted alternative log keys to canonical field names.
26	var fieldAliases = map[string]string{
27		"time":       FieldTimestamp,
28		"src_ip":     FieldSourceIP,
29		"event_type": FieldAction,
30	}
31	
32	// canonicalFieldOrder is the fixed order in which mapped fields are validated,
33	// so the first reported error for a malformed line is deterministic.
34	var canonicalFieldOrder = []string{FieldTimestamp, FieldSourceIP, FieldAction}
35	
36	// NormalizedEvent is the canonical representation of one log line.
37	type NormalizedEvent struct {
38		Timestamp string                     `json:"timestamp"`
39		SourceIP  string                     `json:"source_ip,omitempty"`
40		Action    string                     `json:"action"`
41		Extra     map[string]json.RawMessage `json:"extra,omitempty"`
42	}
43	
44	// NormalizeResult is emitted for every non-blank input line, in input order.
45	type NormalizeResult struct {
46		Line  int              `json:"line"`
47		OK    bool             `json:"ok"`
48		Event *NormalizedEvent `json:"event,omitempty"`
49		Error string           `json:"error,omitempty"`
50	}
51	
52	type fieldCandidate struct {
53		from string
54		raw  json.RawMessage
55	}
56	
57	// NormalizeReader streams newline-delimited JSON logs from r and writes one
58	// NormalizeResult JSON object per non-blank physical line to w. Blank lines
59	// produce no output but still advance the physical line counter. It returns
60	// the number of lines that failed normalization; processing of later lines
61	// continues after any per-line failure.
62	func NormalizeReader(r io.Reader, w io.Writer) (failures int, err error) {
63		reader := bufio.NewReader(r)
64		bw := bufio.NewWriter(w)
65		defer func() {
66			if flushErr := bw.Flush(); err == nil {
67				err = flushErr
68			}
69		}()
70		encoder := json.NewEncoder(bw)
71		encoder.SetEscapeHTML(false)
72	
73		lineNo := 0
74		for {
75			line, readErr := reader.ReadBytes('\n')
76			if len(line) > 0 {
77				lineNo++
78				if strings.TrimSpace(string(line)) != "" {
79					result := NormalizeLine(lineNo, line)
80					if !result.OK {
81						failures++
82					}
83					if encErr := encoder.Encode(result); encErr != nil {
84						return failures, encErr
85					}
86				}
87			}
88			if readErr != nil {
89				if errors.Is(readErr, io.EOF) {
90					return failures, nil
91				}
92				return failures, readErr
93			}
94		}
95	}
96	
97	// NormalizeLine normalizes a single raw JSON log line. The line number is
98	// echoed unchanged in the result.
99	func NormalizeLine(lineNo int, raw []byte) NormalizeResult {
100		event, err := normalizeEvent(bytes.TrimSpace(raw))
101		if err != nil {
102			return NormalizeResult{Line: lineNo, OK: false, Error: err.Error()}
103		}
104		return NormalizeResult{Line: lineNo, OK: true, Event: event}
105	}
106	
107	func normalizeEvent(raw []byte) (*NormalizedEvent, error) {
108		object, err := decodeObject(raw)
109		if err != nil {
110			return nil, err
111		}
112	
113		// Sort source keys so candidate order (and therefore error messages) is
114		// deterministic regardless of Go map iteration order.
115		keys := make([]string, 0, len(object))
116		for key := range object {
117			keys = append(keys, key)
118		}
119		sort.Strings(keys)
120	
121		groups := make(map[string][]fieldCandidate)
122		extra := make(map[string]json.RawMessage)
123		for _, key := range keys {
124			switch key {
125			case FieldTimestamp, FieldSourceIP, FieldAction:
126				groups[key] = append(groups[key], fieldCandidate{from: key, raw: object[key]})
127			default:
128				if canonical, ok := fieldAliases[key]; ok {
129					groups[canonical] = append(groups[canonical], fieldCandidate{from: key, raw: object[key]})
130				} else {
131					extra[key] = object[key]
132				}
133			}
134		}
135	
136		values := make(map[string]string)
137		for _, canonical := range canonicalFieldOrder {
138			candidates := groups[canonical]
139			if len(candidates) == 0 {
140				continue
141			}
142			var canonicalValue string
143			for i, candidate := range candidates {
